1	package com.example.starter.batch;
2	
3	import com.example.starter.batch.dto.ApprovalResponse;
4	import com.example.starter.batch.dto.ApproveRequest;
5	import com.example.starter.batch.dto.BatchHistoryResponse;
6	import com.example.starter.batch.dto.BatchResponse;
7	import com.example.starter.batch.dto.CreateBatchRequest;
8	import com.example.starter.batch.dto.RecallRequest;
9	import com.example.starter.batch.dto.RecallResponse;
10	import com.example.starter.batch.dto.SubmitTestRequest;
11	import com.example.starter.batch.dto.TestResultResponse;
12	import com.fasterxml.jackson.core.JsonProcessingException;
13	import com.fasterxml.jackson.databind.ObjectMapper;
14	import org.springframework.dao.DuplicateKeyException;
15	import org.springframework.stereotype.Service;
16	import org.springframework.transaction.PlatformTransactionManager;
17	import org.springframework.transaction.support.TransactionTemplate;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.Instant;
23	import java.util.HashSet;
24	import java.util.List;
25	import java.util.Set;
26	import java.util.function.Supplier;
27	
28	/**
29	 * 批次隔离与放行核心服务。
30	 *
31	 * <p>并发策略：同一批次的检验/批准/召回在事务内对 batch 行 SELECT ... FOR UPDATE 串行化，
32	 * 按事务提交顺序生效；commandKey 幂等通过 command_log 主键 + 参数指纹实现，
33	 * 同键同参重放返回首次响应快照，同键改参返回 409；仅成功命令写入 command_log。
34	 */
35	@Service
36	public class BatchService {
37	
38	    private static final String CMD_CREATE = "CREATE_BATCH";
39	    private static final String CMD_TEST = "SUBMIT_TEST";
40	    private static final String CMD_APPROVE = "APPROVE";
41	    private static final String CMD_RECALL = "RECALL";
42	
43	    /**
44	     * 指纹拼接分隔符（NUL）：业务参数不可能包含该字符，避免拼接碰撞。
45	     */
46	    private static final String SEP = "\u0000";
47	
48	    private static final int IDEMPOTENCY_MAX_ATTEMPTS = 3;
49	
50	    private final BatchRepository repo;
51	    private final TransactionTemplate tx;
52	    private final ObjectMapper objectMapper;
53	
54	    public BatchService(BatchRepository repo,
55	                        PlatformTransactionManager transactionManager,
56	                        ObjectMapper objectMapper) {
57	        this.repo = repo;
58	        this.tx = new TransactionTemplate(transactionManager);
59	        this.objectMapper = objectMapper;
60	    }
61	
62	    /**
63	     * 创建批次：初始状态 QUARANTINED；batchKey 全局唯一，重复返回 409。
64	     */
65	    public StoredResponse createBatch(CreateBatchRequest req) {
66	        List<String> items = req.requiredTests().stream().map(String::trim).toList();
67	        if (new HashSet<>(items).size() != items.size()) {
68	            throw ApiException.badRequest("requiredTests 存在重复检验项");
69	        }
70	        String fingerprint = fingerprint("create", req.batchKey(), req.productCode(), req.batchNo(),
71	                req.producedAt().toString(), String.join(SEP, items));
72	        return executeIdempotent(CMD_CREATE, req.commandKey(), fingerprint, () -> {
73	            repo.findBatch(req.batchKey()).ifPresent(b -> {
74	                throw ApiException.conflict("batchKey 已存在: " + req.batchKey());
75	            });
76	            String now = now();
77	            repo.insertBatch(new BatchRepository.BatchRow(0L, req.batchKey(), req.productCode(),
78	                    req.batchNo(), req.producedAt().toString(), BatchStatus.QUARANTINED.name(), now));
79	            for (int i = 0; i < items.size(); i++) {
80	                repo.insertRequiredTest(req.batchKey(), items.get(i), i + 1);
81	            }
82	            BatchResponse body = new BatchResponse(req.batchKey(), req.productCode(), req.batchNo(),
83	                    req.producedAt(), BatchStatus.QUARANTINED, items, Instant.parse(now));
84	            return new StoredResponse(201, toJson(body));
85	        });
86	    }
87	
88	    /**
89	     * 提交检验结果：testKey 批次内幂等；任一 FAIL 立即 REJECTED；全部必做项 PASS 后 PENDING_RELEASE。
90	     */
91	    public StoredResponse submitTest(String batchKey, SubmitTestRequest req) {
92	        String fingerprint = fingerprint("test", batchKey, req.testKey(), req.testItem(),
93	                req.result().name(), req.inspector());
94	        return executeIdempotent(CMD_TEST, req.commandKey(), fingerprint, () -> {
95	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
96	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
97	
98	            var existing = repo.findTest(batchKey, req.testKey());
99	            if (existing.isPresent()) {
100	                BatchRepository.TestRow row = existing.get();
101	                boolean sameContent = row.testItem().equals(req.testItem())
102	                        && row.outcome().equals(req.result().name())
103	                        && row.inspector().equals(req.inspector());
104	                if (!sameContent) {
105	                    throw ApiException.conflict("testKey 已以不同内容提交: " + req.testKey());
106	                }
107	                List<String> required = repo.findRequiredTests(batchKey);
108	                BatchStatus snapshot = snapshotAfter(row, repo.findTests(batchKey), required);
109	                return new StoredResponse(200, toJson(toTestResponse(row, snapshot.name())));
110	            }
111	
112	            BatchStatus status = BatchStatus.valueOf(batch.status());
113	            if (status == BatchStatus.REJECTED || status == BatchStatus.RELEASED
114	                    || status == BatchStatus.RECALLED) {
115	                throw ApiException.conflict("批次状态 " + status + " 不允许提交检验");
116	            }
117	            List<String> required = repo.findRequiredTests(batchKey);
118	            if (!required.contains(req.testItem())) {
119	                throw ApiException.unprocessable("检验项不属于该批次必做项: " + req.testItem());
120	            }
121	            boolean itemAlreadyTested = repo.findTests(batchKey).stream()
122	                    .anyMatch(t -> t.testItem().equals(req.testItem()));
123	            if (itemAlreadyTested) {
124	                throw ApiException.conflict("该检验项已存在检验结果: " + req.testItem());
125	            }
126	
127	            String now = now();
128	            repo.insertTest(new BatchRepository.TestRow(0L, batchKey, req.testKey(), req.testItem(),
129	                    req.result().name(), req.inspector(), now));
130	
131	            BatchStatus newStatus = status;
132	            if (req.result() == TestOutcome.FAIL) {
133	                newStatus = BatchStatus.REJECTED;
134	            } else if (status == BatchStatus.QUARANTINED && allRequiredPassed(batchKey, required)) {
135	                newStatus = BatchStatus.PENDING_RELEASE;
136	            }
137	            if (newStatus != status) {
138	                repo.updateStatus(batchKey, newStatus.name());
139	            }
140	            TestResultResponse body = new TestResultResponse(batchKey, req.testKey(), req.testItem(),
141	                    req.result(), req.inspector(), newStatus, Instant.parse(now));
142	            return new StoredResponse(201, toJson(body));
143	        });
144	    }
145	
146	    /**
147	     * 批准：两步放行。首个有效批准进入 RELEASE_REVIEW，第二个不同角色、不同批准人批准后 RELEASED。
148	     */
149	    public StoredResponse approve(String batchKey, String actorId, String roleHeader, ApproveRequest req) {
150	        if (actorId == null || actorId.isBlank()) {
151	            throw ApiException.badRequest("X-Actor-Id 不能为空");
152	        }
153	        ApprovalRole role = parseRole(roleHeader);
154	        String actor = actorId.trim();
155	        String fingerprint = fingerprint("approve", batchKey, actor, role.name());
156	        return executeIdempotent(CMD_APPROVE, req.commandKey(), fingerprint, () -> {
157	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
158	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
159	            BatchStatus status = BatchStatus.valueOf(batch.status());
160	            if (status == BatchStatus.QUARANTINED) {
161	                throw ApiException.unprocessable("必做检验项未全部通过，不能批准");
162	            }
163	            if (status != BatchStatus.PENDING_RELEASE && status != BatchStatus.RELEASE_REVIEW) {
164	                throw ApiException.conflict("批次状态 " + status + " 不允许批准");
165	            }
166	            boolean actorInspected = repo.findTests(batchKey).stream()
167	                    .anyMatch(t -> t.inspector().equals(actor));
168	            if (actorInspected) {
169	                throw ApiException.unprocessable("批准人不得为该批次任一检验结果的检验人: " + actor);
170	            }
171	
172	            List<BatchRepository.ApprovalRow> approvals = repo.findApprovals(batchKey);
173	            String now = now();
174	            int seq;
175	            BatchStatus newStatus;
176	            if (approvals.isEmpty()) {
177	                seq = 1;
178	                newStatus = BatchStatus.RELEASE_REVIEW;
179	            } else {
180	                BatchRepository.ApprovalRow first = approvals.get(0);
181	                if (first.role().equals(role.name())) {
182	                    throw ApiException.conflict("角色 " + role + " 已批准过，需要另一种角色");
183	                }
184	                if (first.actorId().equals(actor)) {
185	                    throw ApiException.conflict("两个批准人必须不同: " + actor);
186	                }
187	                seq = 2;
188	                newStatus = BatchStatus.RELEASED;
189	            }
190	            repo.insertApproval(new BatchRepository.ApprovalRow(0L, batchKey, req.commandKey(),
191	                    actor, role.name(), seq, now));
192	            repo.updateStatus(batchKey, newStatus.name());
193	            ApprovalResponse body = new ApprovalResponse(batchKey, actor, role, seq, newStatus,
194	                    Instant.parse(now));
195	            return new StoredResponse(201, toJson(body));
196	        });
197	    }
198	
199	    /**
200	     * 召回：仅 RELEASED 批次可召回，召回后进入 RECALLED 并不再出现在可用批次查询中。
201	     */
202	    public StoredResponse recall(String batchKey, String actorId, RecallRequest req) {
203	        if (actorId == null || actorId.isBlank()) {
204	            throw ApiException.badRequest("X-Actor-Id 不能为空");
205	        }
206	        String actor = actorId.trim();
207	        String fingerprint = fingerprint("recall", batchKey, actor, req.reason());
208	        return executeIdempotent(CMD_RECALL, req.commandKey(), fingerprint, () -> {
209	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
210	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
211	            BatchStatus status = BatchStatus.valueOf(batch.status());
212	            if (status != BatchStatus.RELEASED) {
213	                throw ApiException.conflict("批次状态 " + status + " 不允许召回，仅 RELEASED 可召回");
214	            }
215	            String now = now();
216	            repo.insertRecall(new BatchRepository.RecallRow(0L, batchKey, req.commandKey(),
217	                    actor, req.reason(), now));
218	            repo.updateStatus(batchKey, BatchStatus.RECALLED.name());
219	            RecallResponse body = new RecallResponse(batchKey, actor, req.reason(),
220	                    BatchStatus.RECALLED, Instant.parse(now));
221	            return new StoredResponse(201, toJson(body));
222	        });
223	    }
224	
225	    /**
226	     * 当前可用批次：排除已召回（RECALLED）批次。
227	     */
228	    public List<BatchResponse> listAvailable() {
229	        return repo.findAvailableBatches().stream().map(this::toBatchResponse).toList();
230	    }
231	
232	    /**
233	     * 批次完整历史：批次概要 + 全部检验 + 全部批准 + 召回记录，历史不因召回而删除或改写。
234	     */
235	    public BatchHistoryResponse history(String batchKey) {
236	        BatchRepository.BatchRow batch = repo.findBatch(batchKey)
237	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
238	        List<String> required = repo.findRequiredTests(batchKey);
239	        List<BatchRepository.TestRow> testRows = repo.findTests(batchKey);
240	        // 按提交顺序推导每条检验结果落定后的批次状态快照：FAIL→REJECTED；
241	        // 必做项全部 PASS 时该条→PENDING_RELEASE；其余→QUARANTINED。
242	        List<TestResultResponse> tests = new java.util.ArrayList<>(testRows.size());
243	        for (BatchRepository.TestRow t : testRows) {
244	            tests.add(toTestResponse(t, snapshotAfter(t, testRows, required).name()));
245	        }
246	        List<ApprovalResponse> approvals = repo.findApprovals(batchKey).stream()
247	                .map(a -> {
248	                    // 历史快照：第一笔批准落定 RELEASE_REVIEW，第二笔落定 RELEASED；不随后续召回改写
249	                    BatchStatus snapshot = a.seq() == 1
250	                            ? BatchStatus.RELEASE_REVIEW
251	                            : BatchStatus.RELEASED;
252	                    return new ApprovalResponse(a.batchKey(), a.actorId(), ApprovalRole.valueOf(a.role()),
253	                            a.seq(), snapshot, Instant.parse(a.createdAt()));
254	                })
255	                .toList();
256	        RecallResponse recall = repo.findRecall(batchKey)
257	                .map(r -> new RecallResponse(r.batchKey(), r.actorId(), r.reason(),
258	                        BatchStatus.RECALLED, Instant.parse(r.createdAt())))
259	                .orElse(null);
260	        return new BatchHistoryResponse(toBatchResponse(batch), tests, approvals, recall);
261	    }
262	
263	    /**
264	     * 幂等执行：同事务内先查 command_log，命中则按指纹返回快照或 409；
265	     * 未命中执行业务动作并写入快照。并发同键插入冲突时重试，读取已提交结果。
266	     */
267	    private StoredResponse executeIdempotent(String type, String commandKey, String fingerprint,
268	                                             Supplier<StoredResponse> action) {
269	        for (int attempt = 0; attempt < IDEMPOTENCY_MAX_ATTEMPTS; attempt++) {
270	            try {
271	                return tx.execute(status -> {
272	                    var existing = repo.findCommand(type, commandKey);
273	                    if (existing.isPresent()) {
274	                        BatchRepository.CommandRow row = existing.get();
275	                        if (!row.fingerprint().equals(fingerprint)) {
276	                            throw ApiException.conflict(
277	                                    "commandKey 已以不同参数使用: " + commandKey);
278	                        }
279	                        return new StoredResponse(row.responseStatus(), row.responseBody());
280	                    }
281	                    StoredResponse response = action.get();
282	                    repo.insertCommand(new BatchRepository.CommandRow(type, commandKey, fingerprint,
283	                            response.status(), response.body()), now());
284	                    return response;
285	                });
286	            } catch (DuplicateKeyException e) {
287	                // 并发同事务键冲突：回滚后重试，读取对方已提交的命令快照或业务结果
288	            }
289	        }
290	        throw ApiException.conflict("命令并发冲突，请重试: " + commandKey);
291	    }
292	
293	    private boolean allRequiredPassed(String batchKey, List<String> required) {
294	        Set<String> passed = new HashSet<>();
295	        for (BatchRepository.TestRow t : repo.findTests(batchKey)) {
296	            if (TestOutcome.PASS.name().equals(t.outcome())) {
297	                passed.add(t.testItem());
298	            }
299	        }
300	        return passed.containsAll(required);
301	    }
302	
303	    private BatchResponse toBatchResponse(BatchRepository.BatchRow row) {
304	        return new BatchResponse(row.batchKey(), row.productCode(), row.batchNo(),
305	                Instant.parse(row.producedAt()), BatchStatus.valueOf(row.status()),
306	                repo.findRequiredTests(row.batchKey()), Instant.parse(row.createdAt()));
307	    }
308	
309	    private TestResultResponse toTestResponse(BatchRepository.TestRow row, String batchStatus) {
310	        return new TestResultResponse(row.batchKey(), row.testKey(), row.testItem(),
311	                TestOutcome.valueOf(row.outcome()), row.inspector(),
312	                BatchStatus.valueOf(batchStatus), Instant.parse(row.createdAt()));
313	    }
314	
315	    /**
316	     * 推导某条检验结果提交落定后的批次状态快照（按检验结果提交顺序）：
317	     * FAIL→REJECTED；此前已有 PASS 已覆盖全部必做项→PENDING_RELEASE；其余→QUARANTINED。
318	     */
319	    private BatchStatus snapshotAfter(BatchRepository.TestRow target,
320	                                      List<BatchRepository.TestRow> ordered,
321	                                      List<String> required) {
322	        if (TestOutcome.FAIL.name().equals(target.outcome())) {
323	            return BatchStatus.REJECTED;
324	        }
325	        Set<String> passed = new HashSet<>();
326	        for (BatchRepository.TestRow t : ordered) {
327	            if (TestOutcome.PASS.name().equals(t.outcome())) {
328	                passed.add(t.testItem());
329	            }
330	            if (t.id() == target.id()) {
331	                break;
332	            }
333	        }
334	        return passed.containsAll(required)
335	                ? BatchStatus.PENDING_RELEASE
336	                : BatchStatus.QUARANTINED;
337	    }
338	
339	    private ApprovalRole parseRole(String roleHeader) {
340	        if (roleHeader == null || roleHeader.isBlank()) {
341	            throw ApiException.badRequest("X-Approval-Role 不能为空");
342	        }
343	        try {
344	            return ApprovalRole.valueOf(roleHeader.trim());
345	        } catch (IllegalArgumentException e) {
346	            throw ApiException.badRequest("X-Approval-Role 必须为 QUALITY 或 OPERATIONS");
347	        }
348	    }
349	
350	    private String toJson(Object body) {
351	        try {
352	            return objectMapper.writeValueAsString(body);
353	        } catch (JsonProcessingException e) {
354	            throw new IllegalStateException("响应序列化失败", e);
355	        }
356	    }
357	
358	    private String now() {
359	        return Instant.now().toString();
360	    }
361	
362	    private String fingerprint(String... parts) {        String canonical = String.join(SEP, parts);
363	        try {
364	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
365	            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
366	            StringBuilder hex = new StringBuilder(hash.length * 2);
367	            for (byte b : hash) {
368	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
369	                hex.append(Character.forDigit(b & 0xF, 16));
370	            }
371	            return hex.toString();
372	        } catch (NoSuchAlgorithmException e) {
373	            throw new IllegalStateException("SHA-256 不可用", e);
374	        }
375	    }
376	}
